import pyomo.environ as pyo

DATA = {
    "supply": [8, 7],
    "demand": [5, 10],
    "cost": [[10, 20], [15, 25]],
    "limit": [[5, 6], [4, 7]],
}


def build_model(data=None):
    d = data or DATA

    n_people = len(d["supply"])
    n_projects = len(d["demand"])

    model = pyo.ConcreteModel()

    model.People = pyo.RangeSet(0, n_people - 1)
    model.Projects = pyo.RangeSet(0, n_projects - 1)

    def cost_lookup(m, i, j):
        return d["cost"][i][j]

    def lim_lookup(m, i, j):
        return d["limit"][i][j]

    def supply_lookup(m, i):
        return d["supply"][i]

    def demand_lookup(m, j):
        return d["demand"][j]

    model.cost = pyo.Param(model.People, model.Projects, initialize=cost_lookup)
    model.limit = pyo.Param(model.People, model.Projects, initialize=lim_lookup)
    model.supply = pyo.Param(model.People, initialize=supply_lookup)
    model.demand = pyo.Param(model.Projects, initialize=demand_lookup)

    def x_bounds(m, i, j):
        return (0, m.limit[i, j])

    model.x = pyo.Var(
        model.People,
        model.Projects,
        domain=pyo.NonNegativeReals,
        bounds=x_bounds,
    )

    def obj_rule(m):
        return sum(
            m.cost[i, j] * m.x[i, j]
            for i in m.People
            for j in m.Projects
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def supply_rule(m, i):
        return sum(m.x[i, j] for j in m.Projects) == m.supply[i]

    model.supply_constraint = pyo.Constraint(model.People, rule=supply_rule)

    def demand_rule(m, j):
        return sum(m.x[i, j] for i in m.People) == m.demand[j]

    model.demand_constraint = pyo.Constraint(model.Projects, rule=demand_rule)

    def limit_rule(m, i, j):
        return m.x[i, j] <= m.limit[i, j]

    model.limit_constraint = pyo.Constraint(
        model.People, model.Projects, rule=limit_rule
    )

    return model


